 require_once dirname(__DIR__,2).'/app/notifications.php';$count=0;foreach(array_unique(array_map('intval',$ids)) as $id){$q=$pdo->prepare("SELECT name,email FROM users WHERE id=? AND role='customer' AND status='active'");$q->execute([$id]);$customer=$q->fetch();if(!$customer||tdc_email_suppressed($customer['email']))continue;$q=$pdo->prepare('SELECT id,amount,created_at FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 1');$q->execute([$id]);$latest=$q->fetch()?:[];$variables=['{{client_name}}'=>htmlspecialchars($customer['name'],ENT_QUOTES,'UTF-8'),'{{amount_paid}}'=>isset($latest['amount'])?'EUR '.number_format((float)$latest['amount'],2):'','{{order_id}}'=>(string)($latest['id']??''),'{{invoice_date}}'=>(string)($latest['created_at']??gmdate('Y-m-d'))];$personal=strtr($body,$variables);require_once dirname(__DIR__,2).'/app/rich_text.php';$html=tdc_rich_text($personal);$text=strip_tags(str_replace(['</p>','</div>','<br>'],"\n",$html))."\n\nTDC TECH\nhttps://tdctech.org";$theme=$pdo->query("SELECT setting_key,setting_value FROM site_settings WHERE setting_key IN ('invoice_header','invoice_footer','invoice_color','invoice_font')")->fetchAll(PDO::FETCH_KEY_PAIR);$color=preg_match('/^#[a-f0-9]{6}$/i',$theme['invoice_color']??'')?$theme['invoice_color']:'#3354aa';$font=in_array($theme['invoice_font']??'', ['Helvetica','Times-Roman','Courier'],true)?$theme['invoice_font']:'Helvetica';$header=htmlspecialchars(strtr($theme['invoice_header']??'TDC TECH',$variables),ENT_QUOTES,'UTF-8');$footer=htmlspecialchars(strtr($theme['invoice_footer']??'TDC TECH | tdctech.org',$variables),ENT_QUOTES,'UTF-8');$brandHtml='<div style="font-family:'.$font.',sans-serif;max-width:640px;margin:auto;padding:24px"><h2 style="background:'.$color.';color:white;padding:20px">'.$header.'</h2>'.$html.'<p>'.$footer.'</p></div>';$pdo->prepare("INSERT INTO notification_outbox(user_id,recipient_email,subject,body_text,body_html,status,created_at,updated_at) VALUES(?,?,?,?,?,'queued',UTC_TIMESTAMP(),U